public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb){
    try {
        if (str == null || session == null || lb == null) {
            throw new IllegalArgumentException("Input parameters cannot be null");
        }
        final int len = str.length();
        final byte[] bytes = new byte[len * 3]; // UTF-8 encoding may take up to 3 bytes per character
        int byteCount = 0;
        for (int i = 0; i < len; i++) {
            char ch = str.charAt(i);
            if (ch < 0x80) {
                bytes[byteCount++] = (byte) ch;
            } else if (ch < 0x800) {
                bytes[byteCount++] = (byte) (0xc0 | (ch >> 6));
                bytes[byteCount++] = (byte) (0x80 | (ch & 0x3f));
            } else {
                bytes[byteCount++] = (byte) (0xe0 | (ch >> 12));
                bytes[byteCount++] = (byte) (0x80 | ((ch >> 6) & 0x3f));
                bytes[byteCount++] = (byte) (0x80 | (ch & 0x3f));
            }
        }
        return writeBytes(bytes, 0, byteCount, session, lb);
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF8 string", e);
    }
}

