private static String substVars(String val, String currentKey, Set<String> cycleSet, Properties props) {
    StringBuilder ret = new StringBuilder();
    Matcher matcher = Pattern.compile("\\$\\{([^}]+)\\}").matcher(val);
    int lastEnd = 0;
    while (matcher.find()) {
        ret.append(val, lastEnd, matcher.start());
        String match = matcher.group(1);
        if (!cycleSet.add(match)) {
            throw new IllegalArgumentException("Infinite loop in properties interpolation for key '" + currentKey + "': " + match);
        }
        String replacement = substVars(props.getProperty(match), match, cycleSet, props);
        if (replacement != null) {
            ret.append(replacement);
        } else {
            ret.append(matcher.group());
        }
        cycleSet.remove(match);
        lastEnd = matcher.end();
    }
    ret.append(val.substring(lastEnd));
    return ret.toString();
}

