List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    try {
        String path = u.getRawPath();
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        if (path != null && !path.isEmpty()) {
            int start = path.startsWith("/") ? 1 : 0;
            int end;
            while ((end = path.indexOf('/', start)) != -1) {
                String segment = path.substring(start, end);
                if (decode) {
                    segment = URLDecoder.decode(segment, StandardCharsets.UTF_8.toString());
                }
                pathSegments.add(new PathSegmentImpl(segment));
                start = end + 1;
            }
            if (start < path.length()) {
                String segment = path.substring(start);
                if (decode) {
                    segment = URLDecoder.decode(segment, StandardCharsets.UTF_8.toString());
                }
                pathSegments.add(new PathSegmentImpl(segment));
            }
        }
        return pathSegments;
    } catch (UnsupportedEncodingException e) {
        // This exception should not occur as UTF-8 is a supported encoding
        throw new RuntimeException(e);
    }
}

