    switch (descriptor.charAt(index)) {
        case 'B':
        case 'C':
        case 'I':
        case 'F':
        case 'S':
        case 'Z':
            // 1-word base type
            // Pop one type from the stack
            break;
        case 'D':
        case 'J':
            // 2-word base type
            // Pop two types from the stack
            break;
        case 'L':
            // Object type
            // Pop one type from the stack
            index = descriptor.indexOf(';', index);
            if (index == -1) {
                throw new IllegalArgumentException("Invalid descriptor format: missing ';'");
            }
            break;
        case '[':
            // Array type
            // Pop one type from the stack
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            index = popType(descriptor, index);
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor format");
    }
    return index + 1;
}

