public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }

    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }

    while (!isPrime(candidate)) {
        candidate += 2;
    }

    if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
        candidate = findClosePrime(desiredCapacity);
    }

    return candidate;
}

private static boolean isPrime(int number) {
    if (number % 2 == 0) {
        return false;
    }
    for (int i = 3; i <= Math.sqrt(number); i += 2) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}

private static int findClosePrime(int desiredCapacity) {
    int lowerBound = (int) (desiredCapacity * 0.89);
    int upperBound = (int) (desiredCapacity * 1.11);

    for (int candidate = desiredCapacity; candidate <= upperBound; candidate++) {
        if (isPrime(candidate)) {
            return candidate;
        }
    }

    for (int candidate = desiredCapacity - 1; candidate >= lowerBound; candidate--) {
        if (isPrime(candidate)) {
            return candidate;
        }
    }

    return desiredCapacity; // Fallback, should rarely reach here
}

