private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.size() < 2) {
        return true; // A single vertex or null inputs form a trivial clique
    }

    for (V u : vertices) {
        if (!graph.containsVertex(u)) {
            return false; // If a vertex is not in the graph, it can't form a clique
        }
        for (V v : vertices) {
            if (!u.equals(v) && !graph.containsEdge(u, v)) {
                return false; // If any two vertices are not connected, it's not a clique
            }
        }
    }

    return true; // All vertices are connected to each other
}

