private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    char c = descriptor.charAt(0);
    if (c == '(') {
        int current = 1;
        while (descriptor.charAt(current) != ')') {
            current = parseType(descriptor, current);
        }
    } else {
        parseType(descriptor, 0);
    }
}

private int parseType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B':
        case 'C':
        case 'D':
        case 'F':
        case 'I':
        case 'J':
        case 'S':
        case 'Z':
            // These are single-slot types
            return index + 1;
        case 'L':
            // Object type, skip to the end of the descriptor for this type
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            return index + 1;
        case '[':
            // Array type, skip the leading '[' and parse the type descriptor that follows
            return parseType(descriptor, index + 1);
        default:
            throw new IllegalArgumentException("Invalid descriptor at index " + index);
    }
}

