String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    // Normalize the paths by replacing backslashes with forward slashes
    String normalizedPath = path.replace('\\', '/');
    String normalizedRelativePath = relativePath.replace('\\', '/');

    // Split the paths into components
    String[] pathComponents = normalizedPath.split("/");
    String[] relativePathComponents = normalizedRelativePath.split("/");

    // Use a stack to help with path traversal
    Stack<String> pathStack = new Stack<>();
    for (String component : pathComponents) {
        if (!component.isEmpty() && !component.equals(".")) {
            if (component.equals("..")) {
                if (!pathStack.isEmpty()) {
                    pathStack.pop();
                }
            } else {
                pathStack.push(component);
            }
        }
    }

    // Process the relative path components
    for (String component : relativePathComponents) {
        if (!component.isEmpty() && !component.equals(".")) {
            if (component.equals("..")) {
                if (!pathStack.isEmpty()) {
                    pathStack.pop();
                }
            } else {
                pathStack.push(component);
            }
        }
    }

    // Join the stack components back into a single string
    return String.join("/", pathStack);
}

